// HasGroup applies the HasEdge predicate on the "group" edge.
func HasGroup() predicate.ChatGroupMember {
	return predicate.ChatGroupMember(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, GroupTable, GroupColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasGroupWith applies the HasEdge predicate on the "group" edge with a given conditions (other predicates).
func HasGroupWith(preds ...predicate.ChatGroup) predicate.ChatGroupMember {
	return predicate.ChatGroupMember(func(s *sql.Selector) {
		step := newGroupStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ChatGroupMember) predicate.ChatGroupMember {
	return predicate.ChatGroupMember(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ChatGroupMember) predicate.ChatGroupMember {
	return predicate.ChatGroupMember(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ChatGroupMember) predicate.ChatGroupMember {
	return predicate.ChatGroupMember(sql.NotPredicates(p))
}
